package actionlint

import (
	"math/big"
	"sort"
)

const (
	// matrixMaxCombinations is GitHub Actions' documented maximum number of jobs generated by one
	// matrix. See:
	// https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax#jobsjob_idstrategymatrix
	matrixMaxCombinations = 256

	// matrixExpansionEnumerationLimit bounds materialized Cartesian expansions. The limit check
	// only needs matrixMaxCombinations+1 combinations to detect an overflow, while exclude matching
	// can be solved analytically. A small multiple leaves room for exact final counts after normal
	// include/exclude usage without allocating millions of maps.
	matrixExpansionEnumerationLimit = 4 * matrixMaxCombinations
)

type matrixCombo map[string]RawYAMLValue

type matrixExpansion struct {
	// rowNames contains original matrix row keys in source order. It is useful for deterministic
	// Cartesian product generation.
	rowNames []string

	// baseProduct is the exact Cartesian product size of the original rows. When there are no
	// original rows, it is zero because an include-only matrix starts with no base combination.
	baseProduct *big.Int

	// base contains every original Cartesian combination. It is nil when baseProduct exceeds the
	// materialization safety limit.
	base []matrixCombo

	// combinations is the final set after exclude and include. It is nil when the expansion was too
	// large to materialize safely.
	combinations []matrixCombo

	// keyCounts is the number of final combinations containing each key.
	keyCounts map[string]int

	// partialKeys contains keys present in some, but not all, final combinations.
	partialKeys map[string]struct{}

	// enumerated reports whether base and combinations were materialized.
	enumerated bool
}

func rawYAMLValueContainsExpression(v RawYAMLValue) bool {
	switch v := v.(type) {
	case *RawYAMLString:
		return ContainsExpression(v.Value)
	case *RawYAMLArray:
		for _, e := range v.Elems {
			if rawYAMLValueContainsExpression(e) {
				return true
			}
		}
	case *RawYAMLObject:
		for _, p := range v.Props {
			if rawYAMLValueContainsExpression(p) {
				return true
			}
		}
	}
	return false
}

// matrixExpansionSupported reports whether a matrix can be expanded without guessing. Expressions
// and mixed object/scalar value shapes intentionally cause all new expansion-based checks to be
// skipped; callers retain the older conservative behavior in that case.
func matrixExpansionSupported(m *Matrix) bool {
	if m == nil || m.Expression != nil {
		return false
	}

	valuesByKey := map[string][]RawYAMLValue{}

	for k, r := range m.Rows {
		if r == nil || r.Expression != nil || (r.Name != nil && ContainsExpression(r.Name.Value)) {
			return false
		}
		for _, v := range r.Values {
			if v == nil || rawYAMLValueContainsExpression(v) {
				return false
			}
			valuesByKey[k] = append(valuesByKey[k], v)
		}
	}

	for _, cs := range []*MatrixCombinations{m.Include, m.Exclude} {
		if cs == nil {
			continue
		}
		if cs.Expression != nil {
			return false
		}
		for _, c := range cs.Combinations {
			if c == nil || c.Expression != nil {
				return false
			}
			for k, a := range c.Assigns {
				if a == nil || a.Value == nil {
					return false
				}
				if a.Key != nil && ContainsExpression(a.Key.Value) {
					return false
				}
				if rawYAMLValueContainsExpression(a.Value) {
					return false
				}
				valuesByKey[k] = append(valuesByKey[k], a.Value)
			}
		}
	}

	// Mixing mappings and scalar values for one matrix key makes the intended shape ambiguous for
	// contextual typing. Be conservative and leave such matrices to the legacy checks.
	for _, vs := range valuesByKey {
		hasObject, hasScalar := false, false
		for _, v := range vs {
			switch v.Kind() {
			case RawYAMLValueKindObject:
				hasObject = true
			case RawYAMLValueKindString:
				hasScalar = true
			}
		}
		if hasObject && hasScalar {
			return false
		}
	}

	return true
}

func sortedMatrixRowNames(m *Matrix) []string {
	names := make([]string, 0, len(m.Rows))
	for n := range m.Rows {
		names = append(names, n)
	}
	sort.Slice(names, func(i, j int) bool {
		ri, rj := m.Rows[names[i]], m.Rows[names[j]]
		if ri != nil && rj != nil && ri.Name != nil && rj.Name != nil {
			if ri.Name.Pos.Line != rj.Name.Pos.Line {
				return ri.Name.Pos.Line < rj.Name.Pos.Line
			}
			if ri.Name.Pos.Col != rj.Name.Pos.Col {
				return ri.Name.Pos.Col < rj.Name.Pos.Col
			}
		}
		return names[i] < names[j]
	})
	return names
}

func cartesianMatrixCombinations(m *Matrix, names []string) []matrixCombo {
	if len(names) == 0 {
		// An include-only matrix has no implicit empty base combination. Every include entry is
		// therefore added as its own new combination.
		return nil
	}

	combos := []matrixCombo{{}}
	for _, name := range names {
		row := m.Rows[name]
		if row == nil {
			return nil
		}
		next := make([]matrixCombo, 0, len(combos)*max(1, len(row.Values)))
		for _, c := range combos {
			for _, v := range row.Values {
				nc := cloneMatrixCombo(c)
				nc[name] = v
				next = append(next, nc)
			}
		}
		combos = next
	}
	return combos
}

func cloneMatrixCombo(c matrixCombo) matrixCombo {
	n := make(matrixCombo, len(c))
	for k, v := range c {
		n[k] = v
	}
	return n
}

func matrixComboMatchesExclude(c matrixCombo, ex *MatrixCombination) bool {
	if ex == nil {
		return false
	}
	for k, a := range ex.Assigns {
		if a == nil {
			return false
		}
		v, ok := c[k]
		if !ok || !isYAMLValueSubset(v, a.Value) {
			return false
		}
	}
	return true
}

// excludeEntryMatchesBase reports whether an exclude entry matches at least one Cartesian base
// combination. When the Cartesian product was not materialized, the same result is obtained
// analytically: a match exists exactly when every constrained row has at least one matching value.
// Choosing one matching value for each constrained row gives a matching Cartesian combination.
func excludeEntryMatchesBase(m *Matrix, exp *matrixExpansion, ex *MatrixCombination) bool {
	if ex == nil {
		return false
	}

	if exp != nil && exp.enumerated {
		for _, c := range exp.base {
			if matrixComboMatchesExclude(c, ex) {
				return true
			}
		}
		return false
	}

	for k, a := range ex.Assigns {
		if a == nil || a.Value == nil {
			return false
		}
		row, ok := m.Rows[k]
		if !ok || row == nil {
			return false
		}
		matched := false
		for _, v := range row.Values {
			if isYAMLValueSubset(v, a.Value) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}
	return true
}

func expandMatrix(m *Matrix) (*matrixExpansion, bool) {
	if !matrixExpansionSupported(m) {
		return nil, false
	}

	names := sortedMatrixRowNames(m)
	product := big.NewInt(1)
	if len(names) == 0 {
		product.SetInt64(0)
	} else {
		for _, n := range names {
			product.Mul(product, big.NewInt(int64(len(m.Rows[n].Values))))
		}
	}

	exp := &matrixExpansion{
		rowNames:    names,
		baseProduct: new(big.Int).Set(product),
		keyCounts:   map[string]int{},
		partialKeys: map[string]struct{}{},
	}

	if !product.IsInt64() || product.Int64() > matrixExpansionEnumerationLimit {
		return exp, true
	}

	exp.enumerated = true
	exp.base = cartesianMatrixCombinations(m, names)

	surviving := make([]matrixCombo, 0, len(exp.base))
	for _, c := range exp.base {
		removed := false
		if m.Exclude != nil {
			for _, ex := range m.Exclude.Combinations {
				if matrixComboMatchesExclude(c, ex) {
					removed = true
					break
				}
			}
		}
		if !removed {
			surviving = append(surviving, cloneMatrixCombo(c))
		}
	}

	added := []matrixCombo{}
	if m.Include != nil {
		for _, inc := range m.Include.Combinations {
			if inc == nil || inc.Expression != nil {
				// Supported matrices never contain include expressions. This guard keeps the helper
				// safe if called with a manually constructed AST.
				return nil, false
			}

			matches := make([]int, 0, len(surviving))
			for i, c := range surviving {
				matchesAllOriginalKeys := true
				for k, a := range inc.Assigns {
					if _, isOriginalRow := m.Rows[k]; !isOriginalRow {
						continue
					}
					v, ok := c[k]
					if a == nil || !ok || !a.Value.Equals(v) {
						matchesAllOriginalKeys = false
						break
					}
				}
				if matchesAllOriginalKeys {
					matches = append(matches, i)
				}
			}

			if len(matches) == 0 {
				c := make(matrixCombo, len(inc.Assigns))
				for k, a := range inc.Assigns {
					if a != nil {
						c[k] = a.Value
					}
				}
				added = append(added, c)
				continue
			}

			for _, i := range matches {
				for k, a := range inc.Assigns {
					if _, isOriginalRow := m.Rows[k]; isOriginalRow || a == nil {
						// Original row values were equality constraints and must not be changed.
						continue
					}
					// Non-original keys may be absent or may have been added by an earlier include
					// entry. GitHub permits those added values to be overwritten.
					surviving[i][k] = a.Value
				}
			}
		}
	}

	exp.combinations = append(surviving, added...)
	for _, c := range exp.combinations {
		for k := range c {
			exp.keyCounts[k]++
		}
	}
	for k, n := range exp.keyCounts {
		if n > 0 && n < len(exp.combinations) {
			exp.partialKeys[k] = struct{}{}
		}
	}

	return exp, true
}
